    '36901': 'alabama power', // Livingston AL — Alabama Power
    '36902': 'alabama power', // Livingston AL — Alabama Power
    '36903': 'alabama power', // Livingston AL — Alabama Power
    '36904': 'alabama power', // Livingston AL — Alabama Power
    '36905': 'alabama power', // Livingston AL — Alabama Power
    '36906': 'alabama power', // Livingston AL — Alabama Power
    '36907': 'alabama power', // Livingston AL — Alabama Power
    '36908': 'alabama power', // Livingston AL — Alabama Power
    '36909': 'alabama power', // Livingston AL — Alabama Power
    '36910': 'alabama power', // Livingston AL — Alabama Power
